def transform_corrected(grid_rows, num_cols):
    rows = len(grid_rows)
    if rows == 0:
        return []

    # Pad grid to uniform width
    grid = []
    for r in range(rows):
        row = list(grid_rows[r])
        while len(row) < num_cols:
            row.append(0)
        grid.append(row)

    # Find 3-bar
    bar_start = None
    for r in range(rows):
        if all(grid[r][c] == 3 for c in range(num_cols)):
            bar_start = r
            break
    if bar_start is None:
        return grid

    # Find end of 3-bar
    bar_end = bar_start
    for r in range(bar_start, rows):
        if not all(grid[r][c] == 3 for c in range(num_cols)):
            break
        bar_end = r + 1

    # Find first complete 3x3 block of 2s in first transmission row
    search_row = 0
    for r in range(rows):
        if r % 6 == 0:
            search_row = r
            break

    first_block_col = None
    for c in range(num_cols - 2):
        if c % 6 == 0 and grid[search_row][c] == 2 and grid[search_row][c+1] == 2 and grid[search_row][c+2] == 2:
            first_block_col = c
            break

    # Create output - start with a copy
    output = [[grid[r][c] for c in range(num_cols)] for r in range(rows)]

    # Transform non-bar rows
    for r in range(rows):
        if bar_start <= r < bar_end:
            continue

        # Transmission row (r % 6 == 0): 2s at transmission cols become 8s
        if r % 6 == 0:
            for c in range(num_cols):
                if c % 6 == 0 and grid[r][c] == 2:
                    output[r][c] = 8

    # Transform bar region - clear all 3s, put specific ghost pattern
    for r in range(bar_start, bar_end):
        for c in range(num_cols):
            # Clear all 3s in bar region
            if grid[r][c] == 3:
                output[r][c] = 0

        if first_block_col is not None:
            row_rel = r - bar_start
            is_trans_row = (r % 6 == 0)

            if row_rel == 0:  # Top of bar - transmission row
                # [2,2,2] at first_block_col, first_block_col+1, first_block_col+2
                output[r][first_block_col] = 2
                if first_block_col + 1 < num_cols:
                    output[r][first_block_col + 1] = 2
                if first_block_col + 2 < num_cols:
                    output[r][first_block_col + 2] = 2

            elif row_rel == 1:  # Middle of bar - transmission row
                # Just 8 at first_block_col
                output[r][first_block_col] = 8

            elif row_rel == 2:  # Bottom-row of bar - non-transmission
                # [2,2,2] at first_block_col-1, first_block_col, first_block_col+1
                if first_block_col - 1 >= 0:
                    output[r][first_block_col - 1] = 2
                output[r][first_block_col] = 2
                if first_block_col + 1 < num_cols:
                    output[r][first_block_col + 1] = 2

            elif row_rel == 3:  # Row below bar - non-transmission
                # [2,2] at first_block_col-1, first_block_col
                if first_block_col - 1 >= 0:
                    output[r][first_block_col - 1] = 2
                output[r][first_block_col] = 2

    return output

